// Category A — a button that shows the current choice of a picker and opens it: a sheet, a menu or a
// popover. It draws a bordered box on the surface, as `TagGroup variant="strong"` draws its chips,
// because it stands in the same filter and toolbar rows they do: the field's name, the value, an
// optional count, then a chevron. Behaviour is React Aria's Button, so it works as the trigger of a
// DialogTrigger, a DrawerTrigger or a MenuTrigger.
//
// The visible text is the accessible name: "월 데이터 모든 용량" or "필터 3" is read as one, so the
// name and the value it shows never disagree (WCAG 2.5.3).
import { Button as AriaButton } from "react-aria-components";
import type { ButtonProps as AriaButtonProps } from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { Badge } from "./Badge";
import { ChevronDown } from "./icons";
import { roleSize, type ControlSize } from "./controlSize";
import "./FieldButton.css";

type FieldButtonSize = ControlSize;

/* The count's Badge size per chip size, chosen so the badge sits inside the box with air above and
   below. The medium Badge overruns an x-small chip and nearly fills a small one; the small Badge
   sits inside x-small, small and medium chips. From large up the medium Badge leaves 10px or more, the same
   air the small one has in a medium chip, so it returns there. */
const BADGE_SIZE: Record<FieldButtonSize, "small" | "medium"> = {
  "x-small": "small",
  small: "small",
  medium: "small",
  large: "medium",
  "x-large": "medium",
};
type FieldButtonShape = "rectangle" | "capsule";

export interface FieldButtonBaseProps
  extends Omit<AriaButtonProps, "className" | "style" | "children" | "value"> {
  /**
   * Size axis: the box's height, inset and radius, the text and the chevron. A picker in a filter
   * row or a toolbar takes `small`, the row's chip height.
   *
   * @default "medium"
   */
  size?: FieldButtonSize;
  /**
   * The box's outline. `capsule` rounds it fully through `radius.full`, for a dropdown chip beside
   * `TagGroup variant="strong"` chips; `rectangle` keeps the brand's control corner, for a toolbar
   * or field-style picker.
   *
   * @default "rectangle"
   */
  shape?: FieldButtonShape;
  /**
   * Fill the container. Off, the box hugs its words, as a chip in a row does; on, it spans a panel
   * or a form column, as a field does.
   *
   * @default false
   */
  isFullWidth?: boolean;
  /**
   * How many choices are applied through the picker, drawn as a brand count after the words
   * ("필터 3"). Omit it, or pass 0, when none is.
   * The count is a `primary` Badge whose size follows the chip's: `small` up to a `medium` chip,
   * `medium` from `large` up, so it always sits inside the box with room above and below.
   */
  count?: number;
}

/** At least one of `label` and `value` is required: together they are the accessible name. */
export type FieldButtonProps = FieldButtonBaseProps &
  (
    | {
        /** The field's name, drawn before the value, or alone as the trigger's word ("필터"). */
        label: string;
        /** The current value, as read ("관악구", "추천순"). */
        value?: ReactNode;
      }
    | { label?: string; value: ReactNode }
  ) & {
    /** Additional class (optional). sd-field-button is always preserved. */
    className?: string;
    /** Forwarded to the underlying <button> DOM node. */
    ref?: Ref<HTMLButtonElement>;
  };

export function FieldButton({
  size = "medium",
  shape = "rectangle",
  isFullWidth = false,
  count,
  label,
  value,
  className,
  ...props
}: FieldButtonProps) {
  const hasValue = value !== undefined && value !== null;
  return (
    <AriaButton
      {...props}
      data-size={size}
      data-shape={shape}
      data-full-width={isFullWidth || undefined}
      // The size-matched label role on the root, as Button carries it: the name, the value and the
      // 1em chevron all take one role and size, so a label-only and a value-only chip match.
      className={
        className
          ? `sd-field-button sd-type-label-${roleSize(size)} ${className}`
          : `sd-field-button sd-type-label-${roleSize(size)}`
      }
    >
      {label !== undefined && (
        // A label standing alone is the trigger's word, so it takes the value's ink, not the muted
        // name ink it carries before a value.
        <span className={`sd-field-button__${hasValue ? "label" : "value"}`}>{label}</span>
      )}
      {hasValue && (
        <span className="sd-field-button__value">{value}</span>
      )}
      {count ? <Badge variant="primary" size={BADGE_SIZE[size]}>{count}</Badge> : null}
      <span aria-hidden="true" className="sd-field-button__icon">
        <ChevronDown size="1em" />
      </span>
    </AriaButton>
  );
}

/* FieldButton.css — .sd-field-button (+ __label · __value · __icon)
   Category A: behaviour borrowed (React Aria Button), look owned. A bordered box on the surface, as
   TagGroup's strong chips are, so a picker and those chips read as one family on a filter row. */
.sd-field-button {
  --sd-field-button-radius-current: var(--sd-field-button-radius-medium);
  --sd-field-button-label-foreground-current: var(--sd-field-button-inside-label-foreground);
  display: inline-flex;
  align-items: center;
  gap: var(--sd-field-button-gap);
  background: var(--sd-field-button-background);
  color: var(--sd-field-button-foreground);
  border: var(--sd-field-button-border-width) solid var(--sd-field-button-border);
  border-radius: var(--sd-field-button-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  outline: none;
}
.sd-field-button[data-size="x-small"] {
  --sd-field-button-radius-current: var(--sd-field-button-radius-x-small);
  height: var(--sd-field-button-height-x-small);
  padding-inline: var(--sd-field-button-padding-inline-x-small);
}
.sd-field-button[data-size="small"] {
  --sd-field-button-radius-current: var(--sd-field-button-radius-small);
  height: var(--sd-field-button-height-small);
  padding-inline: var(--sd-field-button-padding-inline-small);
}
.sd-field-button[data-size="medium"] {
  --sd-field-button-radius-current: var(--sd-field-button-radius-medium);
  height: var(--sd-field-button-height-medium);
  padding-inline: var(--sd-field-button-padding-inline-medium);
}
.sd-field-button[data-size="large"] {
  --sd-field-button-radius-current: var(--sd-field-button-radius-large);
  height: var(--sd-field-button-height-large);
  padding-inline: var(--sd-field-button-padding-inline-large);
}
.sd-field-button[data-size="x-large"] {
  --sd-field-button-radius-current: var(--sd-field-button-radius-x-large);
  height: var(--sd-field-button-height-x-large);
  padding-inline: var(--sd-field-button-padding-inline-x-large);
}
/* A capsule consumes the corner whatever the size, so it draws a round corner, not the curve. */
.sd-field-button[data-shape="capsule"] {
  border-radius: var(--sd-field-button-radius-capsule);
  corner-shape: round;
}
.sd-field-button[data-full-width] {
  width: 100%;
}
/* Hover and press darken the edge and raise the label to the value's ink, as Select's inside label. */
.sd-field-button[data-hovered],
.sd-field-button[data-pressed] {
  --sd-field-button-label-foreground-current: var(--sd-field-button-foreground);
  border-color: var(--sd-field-button-border-hover);
}
.sd-field-button[data-focus-visible] {
  border-color: var(--sd-field-button-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-field-button[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* The name and the value each stand one `text.padding.inline` in, as Button's `__text` does: the
   inset is held as the part's own padding inside the box's padding, never added on top of it
   (component-contract.md § 6 rule 8, a part that declares its own inline padding). Both hug their
   words; only the chevron's auto margin takes the free space, which a hugging box has none of, so it
   reaches the far edge on `isFullWidth` alone. */
.sd-field-button__label,
.sd-field-button__value {
  flex: 0 1 auto;
  min-width: 0;
  padding-inline: var(--sd-field-button-text-padding-inline);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: start;
}
.sd-field-button__label {
  color: var(--sd-field-button-label-foreground-current);
}
/* The chevron is 1em of the root's label role, as Button's trailing icon is. */
.sd-field-button__icon {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-inline-start: auto;
  color: var(--sd-field-button-icon-foreground);
}
